games.schema:
// ~/src/supplies-remake: games, their authors, and lists of games, in
// layered USL (plan 003). Authors are Story accounts, so there is no Person
// model to declare. Who may edit a game is access policy now
// (`who: {property: authors}` in access.yaml), not schema.

main model Game {
  name        Text
  status      Status    // stored as "Draft"
  description Markdown?
  tags        Text[]    // values, stored on the row
  authors     Person[]  // cross-reference: declared below
  lists       List[]    // cross-reference: declared below
}

model List {
  name  Text
  games Game[]  // cross-reference
}

// @fold: in data files, these are arrays on Game and List rows rather than
// files of their own. A storage default; a placement may choose otherwise.
Game.authors[] @fold <-> Person.games[]
ordered List.games[] @fold <-> Game.lists[]
Game.status <-> Status.games[]

enum Status { Draft, Playtested, Polished }

re Game {
  ~views([
    { label: "By game", line: [status ~bullet, name, authors, description], sort: modified },
    { label: "By author", group: authors },
    { label: "By list", group: lists, sort: modified },
  ])
}

re Status {
  Draft      ~color("#9aa0aa")
  Playtested ~color("#bd861a")
  Polished   ~color("#27815a")
}

excellences.schema:
// meaningalignment/excellences: the MAI roles document, in layered USL
// (plan 003). Leads were a `person` collection with a portrait; now they are
// Story accounts, and portraits come from their profiles.

main model Excellence {
  name       Text
  assessment Assessment
  leads      Person[]   // cross-reference
  projects   Project[]  // cross-reference
}

model Project {
  name        Text
  excellences Excellence[]  // cross-reference
}

Excellence.leads[] <-> Person.excellences[]
Excellence.projects[] <-> Project.excellences[]
Excellence.assessment <-> Assessment.excellences[]

enum Assessment { Good, Improving, Bad, "Current focus", "Not recorded" }

re Excellence {
  ~views([
    { label: "By project", line: [name, leads ~label("lead"), assessment ~bullet, projects ~summary ~label("project")], group: projects },
    { label: "By lead", group: leads },
    { label: "By assessment", group: assessment },
  ])
}

re Assessment {
  Good            ~color("#27815a")
  Improving       ~color("#bd861a")
  Bad             ~color("#c25357")
  "Current focus" ~color("#4278c0")
  "Not recorded"  ~color("#9aa0aa")
}

tasks.schema:
// No ~views: the default arrangement. Tasks keep their order within a project.
model Task {
  title   Text
  notes   Markdown?
  points  Int?
  done    Bool
  owner   Person?
  project Project?
  labels  Text[]
}

model Project {
  name  Text
  color Text? ~color
}

ordered Project.tasks[] <-> Task.project?
Task.owner? <-> Person.tasks[]

sorted.schema:
// Members listed by a field of theirs (`~sort`) instead of the order
// they were connected in.

model Game {
  name    Text
  authors Person[]
  tags    Tag[]

  ~views([
    { label: "Games",  line: [name, authors ~sort(name), tags ~sort(name)] },
    { label: "By tag", group: tags ~sort(name) },
  ])
}

model Tag {
  name Text
}

Game.authors[] @fold <-> Person.games[]
Game.tags[] @fold <-> Tag.games[]
